import { PASSWORD, USERS, expect, test } from "../../fixtures";

test("successful sign-in returns a session", { tag: "@AUTH-01" }, async ({ request }) => {
  // Act
  const response = await request.post("/api/auth/login", {
    data: { email: USERS.member, password: PASSWORD },
  });
  const body = await response.text();

  // Assert
  expect(response.status(), body).toBe(200);
  const json = JSON.parse(body) as { access_token?: string };
  expect(json.access_token, body).toBeTruthy();

  const cookie = response
    .headersArray()
    .find((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="));
  expect(cookie, `session cookie missing; headers: ${JSON.stringify(response.headersArray())}`).toBeDefined();
  expect(cookie?.value.toLowerCase(), body).toContain("httponly");
});
